      {l:{en:"Drawings",hi:"आहरण"},r:{en:"Owner takes cash/goods for personal use",hi:"स्वामी निजी उपयोग के लिए नकद/माल लेता है"}},
      {l:{en:"Capital",hi:"पूंजी"},r:{en:"Owner's investment in the business",hi:"व्यवसाय में स्वामी का निवेश"}}
