window.SL_DATA.questions.push(
  { id:"ACC-Q145", board:"CBSE", klass:"11", subject:"ACC", chapter:1, topic:"ACC-1-8", type:"mcq", diff:"hard",
    q:{en:"Case: In April, Meena's shop had cash sales ₹16,300 and credit sales ₹900. She paid rent ₹4,000, wages ₹1,500 and electricity ₹900. She also took ₹1,000 home for family use. What is April's profit?", hi:"Case: अप्रैल में मीना की दुकान की नकद बिक्री ₹16,300 और उधार बिक्री ₹900 रही। उन्होंने किराया ₹4,000, मज़दूरी ₹1,500 और बिजली ₹900 चुकाई। साथ ही घर के लिए ₹1,000 निकाले। अप्रैल का profit कितना है?"},
    opts:{en:["₹9,800","₹10,800","₹8,800","₹17,200"],
          hi:["₹9,800","₹10,800","₹8,800","₹17,200"]},
    correct:"B", exp:{en:"Revenue = 16,300 + 900 = ₹17,200. Expenses = 4,000 + 1,500 + 900 = ₹6,400. Profit = 17,200 − 6,400 = ₹10,800. The ₹1,000 taken home is drawings, not an expense, so it never touches profit.", hi:"आगम = 16,300 + 900 = ₹17,200. व्यय = 4,000 + 1,500 + 900 = ₹6,400. Profit = 17,200 − 6,400 = ₹10,800. घर ले गए ₹1,000 drawings हैं, व्यय नहीं — इसलिए profit पर कोई असर नहीं।"},
    tags:["case","application","numerical","hots","exam-important"], source:"SelfLearn Ch1 case-based", status:"published" },
  { id:"ACC-Q146", board:"CBSE", klass:"11", subject:"ACC", chapter:1, topic:"ACC-1-5", type:"mcq", diff:"hard",
    q:{en:"Case: Meena applies for a loan. The bank sees good profit but also sees that most of her sales are on udhaar and very little cash has come in. What will worry the bank MOST?", hi:"Case: मीना loan के लिए आवेदन करती हैं। Bank को profit तो अच्छा दिखता है, पर यह भी दिखता है कि ज़्यादातर बिक्री उधार पर है और cash बहुत कम आया है। Bank को सबसे ज़्यादा किस बात की चिंता होगी?"},
    opts:{en:["The shop is too small","Whether she will have enough cash to repay the instalments","The colour of her register","That she sells groceries"],
          hi:["दुकान बहुत छोटी है","किस्तें चुकाने के लिए उनके पास पर्याप्त cash होगा या नहीं","उनके register का रंग","वे किराना बेचती हैं"]},
    correct:"B", exp:{en:"A lender's main question is repayment. Profit on paper is not the same as cash in hand — if sales stay locked in udhaar, instalments can still be missed.", hi:"ऋणदाता का मुख्य सवाल भुगतान का है। कागज़ पर profit और हाथ में cash एक बात नहीं — अगर बिक्री उधार में ही फँसी रहे, तो किस्तें छूट सकती हैं।"},
    tags:["case","application","competency","hots","exam-important"], source:"SelfLearn Ch1 case-based", status:"published" },
  { id:"ACC-Q147", board:"CBSE", klass:"11", subject:"ACC", chapter:1, topic:"ACC-1-4", type:"mcq", diff:"hard",
    q:{en:"Case: In one day Meena (i) sold goods ₹2,000, (ii) was praised by a customer, (iii) hired a helper at ₹3,000 a month starting next week, (iv) paid ₹900 electricity. How many of these enter today's books?", hi:"Case: एक दिन में मीना ने (i) ₹2,000 का माल बेचा, (ii) ग्राहक से तारीफ़ पाई, (iii) अगले हफ़्ते से ₹3,000 महीना पर helper रखना तय किया, (iv) ₹900 बिजली चुकाई। इनमें से कितनी बातें आज की किताब में आएँगी?"},
    opts:{en:["All four","Only one","Two — the sale and the electricity","Three — everything except the praise"],
          hi:["चारों","सिर्फ़ एक","दो — बिक्री और बिजली","तीन — तारीफ़ को छोड़कर सब"]},
    correct:"C", exp:{en:"Only money events that have actually happened are recorded. The sale (₹2,000) and electricity (₹900) qualify. Praise cannot be measured in money, and the hiring is only an agreement — no money has moved yet.", hi:"सिर्फ़ वही पैसे वाली घटनाएँ दर्ज होती हैं जो सचमुच हो चुकी हैं। बिक्री (₹2,000) और बिजली (₹900) आएँगी। तारीफ़ पैसे में नहीं मापी जा सकती, और helper रखना अभी सिर्फ़ तय हुआ है — पैसा चला ही नहीं।"},
    tags:["case","application","hots","exam-important"], source:"SelfLearn Ch1 case-based", status:"published" },
  { id:"ACC-Q148", board:"CBSE", klass:"11", subject:"ACC", chapter:1, topic:"ACC-1-8", type:"mcq", diff:"medium",
    q:{en:"Case: On 31 March, Meena asks two questions. (a) Did I earn or lose this year? (b) What do I own and what do I owe today? Which statements answer them, in order?", hi:"Case: 31 मार्च को मीना दो सवाल पूछती हैं। (a) इस साल कमाया या गँवाया? (b) आज मेरे पास क्या है और क्या देना है? क्रम से किन विवरणों से जवाब मिलेगा?"},
    opts:{en:["Balance sheet, then profit & loss account","Profit & loss account, then balance sheet","Both from the balance sheet","Both from the cash memo"],
          hi:["चिट्ठा, फिर profit & loss account","Profit & loss account, फिर चिट्ठा","दोनों चिट्ठे से","दोनों cash memo से"]},
    correct:"B", exp:{en:"Profit or loss for a period comes from the profit & loss account. What the business owns and owes on a date comes from the balance sheet.", hi:"किसी अवधि का profit या loss, profit & loss account से आता है। किसी तारीख़ को क्या अपना है और क्या देना है, वह चिट्ठे से।"},
    tags:["case","application","exam-important"], source:"SelfLearn Ch1 case-based", status:"published" }
);
